class _Safe(dict):
    def __missing__(self, k):
        return "{" + k + "}"


def fmt(lang: str, key: str, **kw) -> dict | str:
    e = T[lang][key]
    if isinstance(e, str):
        return e.format_map(_Safe(kw))
    return {k: v.format_map(_Safe(kw)) for k, v in e.items()}
